<script setup lang="ts">
import {collectionItems,useMediaUrl,type CmsEntry} from '~/composables/useBackend'
import type {BookingService} from '~/types/booking'
useSeoMeta({title:'مرکز مشاوره',description:'آشنایی با خدمات مشاوره، مشاوران و مسیر دریافت نوبت'})
const api=useBackend(),bookingApi=useBookingApi(),mediaUrl=useMediaUrl()
const [{data:counselors,error:counselorError,pending:counselorPending},{data:specialties,error:specialtyError,pending:specialtyPending},{data:serviceResponse},{data:posts,error:postsError,pending:postsPending},{data:pages},{data:faqResponse,error:faqError,pending:faqPending},{data:sections},{data:banners},{data:galleryResponse,error:galleryError,pending:galleryPending},{data:categoryResponse}]=await Promise.all([api.counselors({per_page:4}),api.specialties(),useAsyncData('home-booking-services',()=>bookingApi.services()),api.content('posts',{per_page:4}),api.content('pages'),api.content('faqs',{per_page:4}),api.content('homepage_sections',{per_page:4}),api.content('banners',{per_page:10}),api.content('gallery',{per_page:6}),api.content('categories',{per_page:100})])
const people=computed(()=>collectionItems(counselors.value).slice(0,4)),topics=computed(()=>collectionItems(specialties.value)),articles=computed(()=>collectionItems<CmsEntry>(posts.value).slice(0,4)),bookingServices=computed(()=>collectionItems<BookingService>(serviceResponse.value)),faqs=computed(()=>collectionItems<CmsEntry>(faqResponse.value).slice(0,4)),categories=computed(()=>collectionItems<CmsEntry>(categoryResponse.value))
const homePage=computed(()=>collectionItems<CmsEntry>(pages.value).find(x=>x.slug==='home'||x.slug.endsWith('-home'))),about=computed(()=>collectionItems<CmsEntry>(pages.value).find(x=>x.slug==='about'||x.slug.endsWith('-about')))
const homeSections=computed(()=>collectionItems<CmsEntry>(sections.value)),homeBanners=computed(()=>collectionItems<CmsEntry>(banners.value)),gallery=computed(()=>collectionItems<CmsEntry>(galleryResponse.value).filter(item=>item.image).slice(0,4))
const displayDate=(item:CmsEntry)=>{const value=item.extra?.published_at||item.created_at;if(!value)return '';try{return new Intl.DateTimeFormat('fa-IR-u-ca-persian',{year:'numeric',month:'long',day:'numeric',timeZone:'Asia/Tehran'}).format(new Date(value))}catch{return ''}}
</script>
<template><div class="homepage">
 <HomeHeroSlider :slides="homeBanners" :title="homePage?.title||'آرامش از همین‌جا آغاز می‌شود'" :body="homePage?.body||'برای انتخاب آگاهانه، خدمات و مشاوران مرکز را ببینید و زمان مناسب خود را پیدا کنید.'" :image="homePage?.image?mediaUrl(homePage.image):undefined" :media-url="mediaUrl" :services="bookingServices" :counselors="people"/>
 <section class="container trust-strip" aria-label="امکانات مرکز"><div><span class="trust-mark"></span><span>مشاوران قابل مشاهده در مرکز</span></div><div><span class="trust-mark"></span><span>رزرو نوبت آنلاین</span></div><div><span class="trust-mark"></span><span>انتخاب شیوه برگزاری</span></div><div><span class="trust-mark"></span><span>اطلاعات روشن پیش از پرداخت</span></div></section>
 <section class="container home-specialties"><div class="section-heading"><div><span class="eyebrow">خدمات مرکز</span><h2>از کجا شروع کنیم؟</h2><p>حوزه‌های تخصصی را ببینید و مسیر مناسب خود را پیدا کنید.</p></div><NuxtLink class="text-link" to="/service">همه حوزه‌ها <span aria-hidden="true"><ArrowIcon direction="back" /></span></NuxtLink></div><p v-if="specialtyPending">در حال بارگذاری حوزه‌ها…</p><ApiNotice v-else-if="specialtyError">دریافت تخصص‌ها ناموفق بود.</ApiNotice><div v-else-if="topics.length" class="specialty-grid"><NuxtLink v-for="(item,index) in topics.slice(0,6)" :key="item.id" class="specialty-tile" :class="`tone-${index%6}`" :to="`/service/${item.slug}`"><span class="specialty-icon-wrap"><SpecialtyIcon :name="item.title" :icon="item.extra?.icon"/></span><strong>{{item.title}}</strong><span class="tile-arrow" aria-hidden="true"><ArrowIcon direction="external" /></span></NuxtLink></div><ApiNotice v-else>حوزه تخصصی برای نمایش ثبت نشده است.</ApiNotice></section>
 <section class="home-counselors"><div class="container"><div class="section-heading"><div><span class="eyebrow">همراهی تخصصی</span><h2>با مشاوران مرکز آشنا شوید</h2><p>پروفایل و حوزه‌های کاری هر مشاور را پیش از انتخاب بررسی کنید.</p></div><NuxtLink class="text-link" to="/counselors">جست‌وجوی مشاور <span aria-hidden="true"><ArrowIcon direction="back" /></span></NuxtLink></div><form class="home-counselor-search" action="/counselors"><label class="sr-only" for="home-counselor-search">جست‌وجو میان مشاوران</label><input id="home-counselor-search" name="q" type="search" placeholder="نام مشاور یا حوزه تخصصی را بنویسید"><button type="submit" aria-label="جست‌وجو">جست‌وجو</button></form><p v-if="counselorPending">در حال دریافت اطلاعات مشاوران…</p><ApiNotice v-else-if="counselorError">دریافت فهرست مشاوران ناموفق بود.</ApiNotice><div v-else-if="people.length" class="counselor-grid"><CounselorCard v-for="person in people" :key="person.id" :person="person"/></div><ApiNotice v-else>مشاوری برای نمایش ثبت نشده است.</ApiNotice></div></section>

 <section class="home-mid-banner"><div class="container"><div class="home-mid-banner-card"><img v-if="gallery[0]?.image" :src="mediaUrl(gallery[0].image)" alt="" aria-hidden="true" loading="lazy"><div class="home-mid-banner-copy"><span class="eyebrow">نوبت‌دهی آنلاین</span><h2>جلسه‌ی مناسب‌تان را پیدا کنید</h2><p>خدمات و زمان‌های در دسترس را بررسی کنید.</p><NuxtLink class="btn" to="/appointment">شروع نوبت‌گیری <span aria-hidden="true"><ArrowIcon direction="back" /></span></NuxtLink></div></div></div></section>
 <section v-if="homeSections.length||about" class="home-about"><div class="container home-about-grid"><img v-if="homeSections[0]?.image||about?.image" :src="mediaUrl(homeSections[0]?.image||about?.image)" :alt="homeSections[0]?.title||about?.title||'فضای مرکز مشاوره'" loading="lazy"><div><span class="eyebrow">درباره مرکز</span><h2>{{homeSections[0]?.title||about?.extra?.subtitle||about?.title}}</h2><p class="preline">{{homeSections[0]?.body||about?.body}}</p><NuxtLink class="text-link" to="/about">اطلاعات بیشتر درباره مرکز <span aria-hidden="true"><ArrowIcon direction="back" /></span></NuxtLink></div></div></section>
 <section v-if="articles.length||postsError||postsPending" class="container home-journal">
  <div class="section-heading journal-heading"><div><span class="eyebrow">از مجله پرواز</span><h2>نوشته‌های تازه</h2></div><NuxtLink class="text-link" to="/blog">همه مقاله‌ها <span aria-hidden="true"><ArrowIcon direction="back" /></span></NuxtLink></div>
  <p v-if="postsPending">در حال دریافت مقاله‌ها…</p><ApiNotice v-else-if="postsError">مطالب موقتاً در دسترس نیستند.</ApiNotice>
  <div v-else-if="articles.length" class="journal-grid">
   <NuxtLink v-for="item in articles" :key="item.id" class="journal-card" :to="`/blog/${item.slug}`">
    <div class="journal-card-image"><img v-if="item.image" :src="mediaUrl(item.image)" :alt="item.title" loading="lazy" decoding="async"><span v-else class="journal-image-fallback" aria-hidden="true"><span>مجله پرواز</span></span><span v-if="item.extra?.category_slug" class="journal-category">{{categories.find(category=>category.slug===item.extra?.category_slug)?.title||item.extra.category_slug}}</span></div>
    <div class="journal-card-copy"><time v-if="displayDate(item)" class="muted">{{displayDate(item)}}</time><h3>{{item.title}}</h3><p class="preline">{{item.body}}</p><span class="text-link">ادامه مطلب <span aria-hidden="true"><ArrowIcon direction="back" /></span></span></div>
   </NuxtLink>
  </div>
 </section>
 <section v-if="galleryPending||galleryError||gallery.length" class="home-gallery-section"><div class="container"><div class="section-heading"><div><span class="eyebrow">فضای مرکز</span><h2>نگاهی به گالری</h2></div><NuxtLink class="text-link" to="/gallery">همه تصاویر <span aria-hidden="true"><ArrowIcon direction="back" /></span></NuxtLink></div><p v-if="galleryPending">در حال دریافت تصاویر…</p><ApiNotice v-else-if="galleryError">تصاویر گالری موقتاً در دسترس نیستند.</ApiNotice><div v-else-if="gallery.length" class="home-gallery"> <NuxtLink v-for="(item,index) in gallery" :key="item.id" to="/gallery" class="home-gallery-item" :class="`gallery-piece-${index+1}`"><img v-if="item.image" :src="mediaUrl(item.image)" :alt="item.title||'تصویر گالری مرکز'" loading="lazy"><span v-if="item.title">{{item.title}}</span></NuxtLink></div></div></section>
 <section v-if="faqPending||faqError||faqs.length" class="home-faq"><div class="container home-faq-grid"><div><span class="eyebrow">پیش از رزرو</span><h2>پرسش‌های متداول</h2><p>پاسخ پرسش‌های رایج درباره خدمات و مسیر نوبت‌گیری.</p><NuxtLink class="text-link" to="/faq">دیدن همه پرسش‌ها <span aria-hidden="true"><ArrowIcon direction="back" /></span></NuxtLink></div><div><p v-if="faqPending">در حال دریافت پرسش‌ها…</p><ApiNotice v-else-if="faqError">پرسش‌ها موقتاً در دسترس نیستند.</ApiNotice><details v-else v-for="item in faqs" :key="item.id" class="home-faq-item"><summary>{{item.title}}</summary><p class="preline">{{item.body}}</p></details></div></div></section>
 <section class="home-last-cta"><div class="container home-last-card"><div><span class="eyebrow">قدم بعدی با انتخاب شماست</span><h2>برای بررسی زمان‌های موجود آماده‌اید؟</h2><p>جزئیات نوبت را در حساب کاربری‌تان ببینید و پرداخت را تکمیل کنید.</p></div><NuxtLink class="btn" to="/appointment">شروع نوبت‌گیری</NuxtLink></div></section>
</div></template>
